class Solution {
    public boolean isPowerOfThree(int n) {
        if (n <= 0) return false;

        // Check if n is a power of 3 using bit manipulation.
        // A power of 3 in binary has only one bit set to 1.
        // The largest power of 3 that fits within the 32-bit integer range is 3^19 = 1162261467.
        // The binary representation of powers of 3 will have the form 1000...001.
        // We can check if n is a power of 3 by checking if n is divisible by 3 and if the bitwise AND of n and 879228147 is equal to 0.
        // 879228147 is 3^19.
        return (n > 0) && ((n & 0x7fffffff) == (879228147 & 0x7fffffff));
    }
}
```

